'use strict';
const $=s=>document.querySelector(s), esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])), num=x=>Number(x||0).toLocaleString(), pct=x=>(100*Number(x||0)).toFixed(2)+'%', date=x=>new Date(x*1000).toLocaleString();
let user=null,csrf='',models=[],defaultModel=null,analyses=[],timer=null,register=false,activeId=null,page=0,classFilter='all',generation=0,incidentFilter={},dashboardIncidents=null;
const classes=['benign','recon','ae_bruteforce','assoc_flood','malformed_pdu','ransomware_like','exfiltration','preamble_polyglot'];
const brand='<a href="#dashboard" class="brand"><img src="/favicon.svg" alt=""><div>Aesculyn<small>Imaging security workspace</small></div></a>';
const art='<svg viewBox="0 0 240 220" role="img" aria-label="Medical imaging scanner and security shield"><rect x="14" y="172" width="210" height="13" rx="6" fill="#bddbd3"/><rect x="55" y="37" width="118" height="137" rx="28" fill="#fff" stroke="#b4d7cd" stroke-width="3"/><circle cx="114" cy="99" r="42" fill="#cde5de"/><circle cx="114" cy="99" r="30" fill="#f5fbf9"/><rect x="103" y="115" width="20" height="62" rx="8" fill="#a8cfc3"/><rect x="87" y="128" width="116" height="15" rx="7" fill="#fff" stroke="#b4d7cd" stroke-width="2"/><rect x="184" y="141" width="10" height="35" fill="#9bc8bb"/><path d="m181 26 35 13v30c0 25-35 44-35 44s-35-19-35-44V39z" fill="#16898d"/><path d="M175 47h12v11h11v12h-11v11h-12V70h-11V58h11z" fill="#f2fffa"/><path d="M20 150h20l8-16 11 28 10-12h18" fill="none" stroke="#65ac98" stroke-width="3" stroke-linecap="round"/></svg>';
function toast(t){$('#toast').textContent=t;$('#toast').style.display='block';setTimeout(()=>$('#toast').style.display='none',4500)}
async function api(path,options={}){const headers={...(options.body instanceof File?{}:{'Content-Type':'application/json'}),...(options.headers||{})};if(options.method&&options.method!=='GET'&&csrf)headers['X-CSRF-Token']=csrf;const r=await fetch('/api'+path,{...options,headers,credentials:'same-origin'});const d=await r.json();if(!r.ok){if(r.status===401&&user){user=null;auth()}throw Error(d.error||'Request failed.')}return d}
function badge(r){return `<span class="badge ${esc(r.status)}">${esc(r.status)}</span>`}
function nav(){return [['dashboard','◫','Overview'],['new','＋','New analysis'],['history','▤','Analysis history'],['models','◇','Model registry'],['evidence','⌁','Research evidence'],['workbench','⌘','Local work & training'],['captures','⇧','Offline PCAP'],['incidents','⚑','Incident review'],['policy','⚙','Rules & dry-run policy'],['settings','⚙','Workspace']].map(([id,icon,label])=>`<a href="#${id}" class="${location.hash.slice(1)===id?'active':''}"><span>${icon}</span>${label}</a>`).join('')}
function shell(){ $('#app').innerHTML=`<aside class="sidebar">${brand}<nav aria-label="Main navigation">${nav()}</nav><footer><span class="badge">Offline analysis</span><p>Decision support for research.<br>Every prediction needs context.</p><a href="https://ashubshafqat.github.io/aesculyn/" target="_blank" rel="noopener">Public research showcase ↗</a></footer></aside><div class="workspace"><header class="topbar"><div><div class="eyebrow">Your private workspace</div><strong>${esc(user.workspace)}</strong></div><div class="account"><div class="avatar">${esc(user.name[0].toUpperCase())}</div><span>${esc(user.name)}</span><button class="secondary small" id="logout">Sign out</button></div></header><main class="content" id="content" tabindex="-1"></main></div>`;$('#logout').onclick=async()=>{try{await api('/auth/logout',{method:'POST'});user=null;csrf='';clearTimeout(timer);auth()}catch(e){toast(e.message)}}}
function auth(){clearTimeout(timer);$('#app').innerHTML=`<main class="auth"><section class="auth-story">${brand}<div><div class="eyebrow">A clearer view of imaging security</div><h1>Understand the signals.<br>Protect the care.</h1><p>A dedicated workspace to examine DICOM network features, review model predictions, and understand the evidence behind them.</p></div><div class="auth-art">${art}</div><footer class="tiny muted">Experimental offline analysis · No connection to hospital systems</footer></section><section class="auth-main"><div class="auth-box"><div class="eyebrow">Aesculyn workspace</div><h1>${register?'Create your account':'Welcome back'}</h1><p class="sub">${register?'Start a private analysis workspace on this server.':'Sign in to continue your analysis.'}</p><form id="authform" class="form">${register?'<label for="name">Your name</label><input id="name" name="name" autocomplete="name" maxlength="80" required>':''}<label for="email">Email address</label><input type="email" id="email" name="email" autocomplete="username" maxlength="254" required><label for="password">Password</label><input type="password" id="password" name="password" autocomplete="${register?'new-password':'current-password'}" minlength="12" maxlength="128" required><p class="tiny muted">Use 12–128 characters. Accounts belong to this server.</p><div id="autherror" role="alert"></div><button type="submit">${register?'Create workspace':'Sign in'} →</button></form><button id="switch" class="switch">${register?'Already have an account? Sign in':'New here? Create an account'}</button><div class="notice">Research software. This application analyzes uploaded feature CSVs. It does not monitor a hospital network or block attacks. Do not upload patient identifiers.</div></div></section></main>`;$('#switch').onclick=()=>{register=!register;auth()};$('#authform').onsubmit=async e=>{e.preventDefault();const button=e.target.querySelector('button');button.disabled=true;try{const d=await api('/auth/'+(register?'register':'login'),{method:'POST',body:JSON.stringify(Object.fromEntries(new FormData(e.target)))});user=d.user;csrf=d.csrf;location.hash='dashboard';await route()}catch(err){$('#autherror').innerHTML=`<p class="error">${esc(err.message)}</p>`}finally{button.disabled=false}}}
function stat(label,value,note){return `<div class="card"><div class="stat-label">${label}<span>↗</span></div><div class="stat-value">${value}</div><div class="stat-note">${note}</div></div>`}
function table(items){if(!items.length)return '<div class="empty"><div class="empty-symbol">▤</div><b>Your analysis history starts here</b>Upload a feature CSV to create your first analysis.<p><a class="button small" href="#new">Start an analysis</a></p></div>';return `<div class="table-wrap"><table><thead><tr><th>Analysis</th><th>Records</th><th>Status</th><th>Created</th><th></th></tr></thead><tbody>${items.map(r=>`<tr><td>${esc(r.name)}<div class="tiny muted">${esc(r.model_id)}</div></td><td>${num(r.rows)}</td><td>${badge(r)}</td><td>${esc(date(r.created))}</td><td><a href="#analysis/${r.id}">Open →</a></td></tr>`).join('')}</tbody></table></div>`}
function bars(counts){const max=Math.max(1,...Object.values(counts));return Object.entries(counts).map(([c,n])=>`<div class="bar-row"><span>${esc(c.replaceAll('_',' '))}</span><div class="track"><div class="fill ${c==='benign'?'':'review'}" style="width:${n/max*100}%"></div></div><b>${num(n)}</b></div>`).join('')}
function dashboard(){const done=analyses.filter(r=>r.status==='completed'),rows=done.reduce((s,r)=>s+r.rows,0),review=done.reduce((s,r)=>s+r.summary.malicious_predictions,0),running=analyses.filter(r=>['running','queued'].includes(r.status)).length;return `<section class="hero"><div><div class="eyebrow">Security in service of care</div><h1>Your imaging security,<br>with a clearer perspective.</h1><p>Turn network feature records into reviewable predictions. Keep the model, the explanation, and the evidence together.</p><a class="button" href="#new">＋ New analysis</a> <span class="tiny muted">Private to your account</span></div><div class="hero-art">${art}</div></section><div class="stats">${stat('Completed analyses',num(done.length),'Saved in this workspace')}${stat('Records analyzed',num(rows),'Across completed batches')}${stat('Predictions to review',num(review),'Non-benign model predictions')}${stat('Active analyses',num(running),'Queued or processing')}</div><div class="grid"><section class="card"><div class="row between"><h2>Recent analyses</h2><a class="tiny" href="#history">View all →</a></div>${table(analyses.slice(0,5))}</section><section class="card"><h2>Your review overview</h2>${rows?`<div class="distribution"><div class="donut" style="background:conic-gradient(#dfad60 ${review/rows*360}deg,#16898d 0deg)"><span>${num(rows)}<small>records</small></span></div><div class="legend"><span class="dot"></span>Benign prediction <b>${num(rows-review)}</b><br><span class="dot gold"></span>Review required <b>${num(review)}</b></div></div>`:'<p class="muted">No completed batches yet. This chart will show your actual analysis results.</p>'}<div class="notice">A non-benign prediction is a review flag, not proof of an attack. A benign prediction does not guarantee safety.</div><a class="tiny" href="#models">Inspect model evidence →</a></section></div><section class="card"><div class="row between"><h2>Recent review items</h2><a class="tiny" href="#incidents">Open incident review →</a></div>${dashboardIncidents?.incidents?.length?`<div class="table-wrap"><table><thead><tr><th>Prediction</th><th>Level</th><th>Review</th><th></th></tr></thead><tbody>${dashboardIncidents.incidents.slice(0,5).map(i=>`<tr><td>${esc(i.prediction)}</td><td>${['','Watch','Restrict','Quarantine'][i.level]}</td><td>${esc(i.status)}</td><td><a href="#incident/${i.id}">Open →</a></td></tr>`).join('')}</tbody></table></div>`:'<p class="muted">No alert records in this workspace. New model and rule detections will appear after analysis.</p>'}</section><section class="card"><h2>A thoughtful analysis workflow</h2><div class="grid equal"><div class="step"><span class="step-number">1</span><div><b>Upload validated features</b><span class="muted">Use the documented 25 network features. Identifiers and extra columns are excluded from stored inputs.</span></div></div><div class="step"><span class="step-number">2</span><div><b>Review, explain, export</b><span class="muted">Inspect class predictions, input range checks, local attributions, and downloadable reports.</span></div></div></div></section>`}
function newAnalysis(){return `<div class="heading"><div><div class="eyebrow">Offline batch inference</div><h1>Start a new analysis</h1><p class="sub">A structured upload. A traceable result.</p></div><a class="button secondary small" href="/api/template">↓ CSV template</a></div><div class="grid"><section class="card"><h2>Upload network feature records</h2><form id="upload" class="form"><label for="file">Feature CSV · UTF-8 · up to 5 MB / 10,000 records</label><input id="file" name="file" type="file" accept=".csv,text/csv" required><label for="model">Model checkpoint</label><select id="model">${models.map(m=>`<option value="${esc(m.id)}" ${m.id===defaultModel?'selected':''}>${esc(m.name)} · seed ${m.seed}${m.id===defaultModel?' · Recommended from study validation':''}</option>`).join('')}</select><p class="tiny muted">The default is the centralized MLP family selected by validation macro-F1. Seed 17 was fixed before deployment; it is not a test-selected checkpoint.</p><div id="uploaderror" role="alert"></div><button ${models.length?'':'disabled'} type="submit">Analyze CSV →</button></form></section><aside class="stack"><section class="card"><h2>Before you upload</h2><div class="steps"><div class="step"><span class="step-number">1</span><div><b>Use the training schema</b><span class="muted">25 numeric, non-negative features; event and packet counters must be integers. No missing values.</span></div></div><div class="step"><span class="step-number">2</span><div><b>Keep patient data out</b><span class="muted">Upload extracted network statistics, not DICOM images, patient records, PCAPs, or credentials.</span></div></div><div class="step"><span class="step-number">3</span><div><b>Labels are optional</b><span class="muted">Include label_class only when you have known labels. They are used for evaluation, never as model inputs.</span></div></div></div></section><div class="notice">This action runs inference using a saved checkpoint. It does not retrain the model or join a federated network. The research training pipeline is included in the source.</div></aside></div><section class="card"><h2>Required features</h2><div class="features">${(models[0]?.features||[]).map(f=>`<div>${esc(f)}</div>`).join('')}</div></section>`}
function registry(){return `<div class="eyebrow">Versioned & traceable</div><h1>Model registry</h1><p class="sub">Measured study results, with the limits visible.</p><div class="notice">All checkpoints use the same experimental corpus and unseen-site diagnostic protocol. Three-seed family averages are distinct from the single checkpoint used for your prediction. No independent hospital validation, calibrated confidence, differential privacy, or secure aggregation is claimed.</div><div class="model-grid">${models.map(m=>`<article class="card"><div class="row between"><span class="badge">${m.default?'Default model':'Available checkpoint'}</span><span class="tiny muted">Seed ${m.seed}</span></div><h2 style="margin-top:22px">${esc(m.name)}</h2><code>${esc(m.id)}</code><p class="tiny muted">25 → 64 → 32 → 8 · ReLU MLP<br>Training-only log1p normalization</p><h3>This checkpoint · held-out test</h3><div class="metric-pair"><div><b>${pct(m.test.accuracy)}</b><span>Accuracy</span></div><div><b>${pct(m.test.macro_f1)}</b><span>Macro-F1</span></div></div><p class="tiny">Attack → benign misses: <b>${num(m.test.false_negatives)}</b><br>False-negative rate: <b>${pct(m.test.false_negative_rate)}</b><br>False-positive rate: <b>${pct(m.test.false_positive_rate)}</b><br>Validation macro-F1: <b>${pct(m.validation.macro_f1)}</b></p><h3>Family average · 3 seeds</h3><p class="tiny muted">Accuracy ${pct(m.family_test_mean.accuracy)}<br>Macro-F1 ${pct(m.family_test_mean.macro_f1)}</p><p class="tiny muted">${esc(m.selection)}</p><details><summary class="tiny">Integrity & limitations</summary><p class="tiny">Checkpoint SHA-256</p><code class="hash">${esc(m.sha256)}</code><ul>${m.limitations.map(s=>`<li>${esc(s)}</li>`).join('')}</ul></details></article>`).join('')}</div>`}
async function evidence(){const r=await api('/research');return `<div class="eyebrow">Reproducible research · saved experiment</div><h1>Research analytics</h1><p class="sub">Explore model comparisons, site-specific performance, confusions and federation rounds from the completed study.</p><div class="notice">Every graph is rendered from the saved experiment report. These are diagnostic reuse results from one collection run; three seeds quantify initialization variation, not new independent hospitals.</div><div class="stats">${stat('Training seeds',r.configuration.seeds.length,'17, 29, 43')}${stat('Federated rounds',r.configuration.rounds,'Recorded local updates')}${stat('Sites',3,'Dataset client partitions')}${stat('Dataset SHA-256',r.dataset_sha256.slice(0,12)+'…','Pinned in experiment report')}</div><div class="toolbar row"><label>Protocol <select id="analyticsProtocol"><option value="unseen_site">A/B train → unseen C test</option><option value="temporal_federation">A/B/C train → later test</option></select></label><label>Federation seed <select id="analyticsSeed">${r.configuration.seeds.map(s=>`<option>${s}</option>`).join('')}</select></label><button class="secondary small" id="downloadMetrics">↓ Metrics CSV</button><a class="button secondary small" href="/api/research" download="aesculyn-research.json">↓ Source report JSON</a></div><div id="analyticsCharts"></div><div class="grid equal"><section class="card"><h2>Research interpretation</h2><p>The old eight-class comparison retains A6 preamble_polyglot as a learned class. The architecture brief specifies A6 as a separate rule layer for its new seven-class design. The two designs are not merged.</p><p>Federated clients are local processes on one computer. The transcript contains transmitted parameter byte counts but no secure aggregation or differential privacy.</p><a class="button secondary small" href="https://ashubshafqat.github.io/aesculyn/#research" target="_blank" rel="noopener">Open public report ↗</a></section><section class="card"><h2>Evaluation boundaries</h2><div class="notice">Test outputs were inspected in the earlier work. No untouched prospective hospital holdout or independent-run replication exists. Research results are not clinically validated.</div><p class="tiny muted">Class imbalances, duplicate removal, label audit and 60-second split purge are described in the source report and data audit.</p></section></div>`}
function drawAnalytics(r){const protocol=$('#analyticsProtocol').value,seed=Number($('#analyticsSeed').value),group=r.results[protocol],models=group.models,method=m=>({gaussian_nb:'Gaussian NB',logistic_regression:'Logistic regression',random_forest:'Histogram random forest',central_mlp:'Centralized MLP',fedavg:'FedAvg MLP',fedprox:'FedProx MLP'})[m]||m;const colors=['#16898d','#7392be','#d2a54c','#7559a2','#55a677','#cf6d68'];const width=780,left=190,right=735,row=51,top=35,height=70+models.length*row;const comparison=models.map((m,i)=>{const val=Math.max(0,Math.min(1,m.test.macro_f1.mean)),sd=m.test.macro_f1.std||0,x=left+(right-left)*val,vy=left+(right-left)*m.validation_macro_f1_mean;return `<text x="${left-10}" y="${top+i*row+17}" text-anchor="end" font-size="11" fill="#355c67">${esc(method(m.method))}</text><rect x="${left}" y="${top+i*row}" width="${Math.max(1,x-left)}" height="19" rx="4" fill="${colors[i%colors.length]}"/><line x1="${left+(right-left)*Math.max(0,val-sd)}" x2="${left+(right-left)*Math.min(1,val+sd)}" y1="${top+i*row+9}" y2="${top+i*row+9}" stroke="#173d47" stroke-width="2"/><circle cx="${vy}" cy="${top+i*row+28}" r="4" fill="#173d47"/><text x="${right+9}" y="${top+i*row+14}" font-size="10" fill="#355c67">${pct(val)} ± ${pct(sd)}</text><text x="${left-5}" y="${top+i*row+34}" font-size="9" fill="#607b84">Val ${pct(m.validation_macro_f1_mean)} · Test N=${num(m.test.records.mean)}</text>`}).join('');const ticks=[0,.25,.5,.75,1].map(v=>{const x=left+(right-left)*v;return `<line x1="${x}" x2="${x}" y1="20" y2="${height-9}" stroke="#e6eef0"/><text x="${x}" y="${height}" text-anchor="middle" font-size="10" fill="#536c7a">${Math.round(v*100)}%</text>`}).join('');const svg=`<svg id="comparisonSVG" xmlns="http://www.w3.org/2000/svg" viewBox="0 0 ${width+80} ${height+12}" role="img" aria-label="Held-out test macro-F1 by method. Bars are test mean; ranges are seed standard deviations; circles are validation mean">${ticks}${comparison}<text x="${left}" y="14" font-size="10" fill="#355c67">Held-out test macro-F1 · bar ± SD; dot is validation mean</text></svg>`;const selected=models.find(x=>x.method===group.selected_method),per=selected?.per_seed.find(x=>x.seed===seed)||selected?.per_seed[0],cm=per?.test.confusion_matrix||[],classes=Object.keys(r.audit.class_counts);const matrix=cm.length?`<div class="table-wrap"><table><thead><tr><th>Actual ↓ / predicted →</th>${classes.map(c=>`<th>${esc(c)}</th>`).join('')}</tr></thead><tbody>${cm.map((line,i)=>{const max=Math.max(...line,1);return `<tr><td>${esc(classes[i])}</td>${line.map((v,j)=>`<td style="background:rgba(8,125,130,${Math.max(.03,v/max*.55)})" title="${num(v)} records">${num(v)}</td>`).join('')}</tr>`}).join('')}</tbody></table></div>`:'<p>No held-out confusion matrix in report.';const federated=['fedavg','fedprox'].map((m,mi)=>r.federated_runs[`${protocol}/${seed}/${m}`]).filter(Boolean);const chart=`<svg id="federatedSVG" xmlns="http://www.w3.org/2000/svg" viewBox="0 0 700 210" role="img" aria-label="Validation macro-F1 by recorded federation round">${[0,.25,.5,.75,1].map(v=>{const y=180-v*150;return `<line x1="42" x2="680" y1="${y}" y2="${y}" stroke="#e5edef"/><text x="36" y="${y+3}" font-size="9" text-anchor="end" fill="#647d87">${Math.round(v*100)}%</text>`}).join('')}${federated.map((m,mi)=>`<polyline fill="none" stroke="${mi?'#b77939':'#087d82'}" stroke-width="2.5" points="${m.history.map((x,i)=>`${42+638*i/Math.max(1,m.history.length-1)},${180-150*x.validation_macro_f1}`).join(' ')}"/><text x="${50+mi*140}" y="204" font-size="10" fill="${mi?'#b77939':'#087d82'}">${esc(method(m.strategy))} · ${m.rounds} rounds</text>`).join('')}</svg>`;$('#analyticsCharts').innerHTML=`<section class="card"><div class="row between"><h2>Model comparison · ${esc(group.selected_method)} selected by validation</h2><div><button class="secondary small" id="svgComparison">↓ Comparison SVG</button> <button class="secondary small" id="pngComparison">↓ Comparison PNG</button></div></div><div class="table-wrap">${svg}</div><p class="tiny muted">Points show mean validation macro-F1. Bars show held-out test mean across seeds with sample SD. Test scores do not select the model.</p></section><div class="grid equal" style="margin-top:20px"><section class="card"><h2>Confusion matrix · ${esc(method(selected?.method||''))}, seed ${per?.seed||seed}</h2><p class="tiny muted">Rows are actual classes; columns are predicted. Cell shading scales within each actual class.</p>${matrix}</section><section class="card"><div class="row between"><h2>Federated validation rounds · seed ${seed}</h2><button class="secondary small" id="svgFederated">↓ SVG</button></div>${chart}<p class="tiny muted">Actual process-isolated training logs. Validation curves are checkpoint selection data, not final test curves.</p></section></div><section class="card"><h2>Client class counts</h2><p class="tiny muted">Observed training partitions; class counts are not inferred from model outputs.</p><div class="grid equal">${Object.entries(r.audit.site_class_counts||{}).map(([site,counts])=>`<div><h3>Site ${esc(site)}</h3>${bars(counts)}</div>`).join('')}</div></section>`;$('#svgComparison').onclick=()=>saveSVG('comparisonSVG','aesculyn-model-comparison.svg');$('#svgFederated').onclick=()=>saveSVG('federatedSVG','aesculyn-federated-rounds.svg');$('#pngComparison').onclick=()=>savePNG('comparisonSVG','aesculyn-model-comparison.png');$('#downloadMetrics').onclick=()=>{};}
function saveSVG(id,name){const el=$('#'+id),xml=new XMLSerializer().serializeToString(el),a=document.createElement('a'),url=URL.createObjectURL(new Blob([xml],{type:'image/svg+xml'}));a.href=url;a.download=name;a.click();URL.revokeObjectURL(url)}
function savePNG(id,name){const el=$('#'+id),xml=new XMLSerializer().serializeToString(el),url=URL.createObjectURL(new Blob([xml],{type:'image/svg+xml'})),image=new Image();image.onload=()=>{const box=el.viewBox.baseVal,c=document.createElement('canvas');c.width=box.width*2;c.height=box.height*2;const ctx=c.getContext('2d');ctx.scale(2,2);ctx.drawImage(image,0,0);c.toBlob(blob=>{const u=URL.createObjectURL(blob),a=document.createElement('a');a.href=u;a.download=name;a.click();URL.revokeObjectURL(u);URL.revokeObjectURL(url)},'image/png')};image.src=url}
function bindAnalytics(r){const redraw=()=>drawAnalytics(r);$('#analyticsProtocol').onchange=redraw;$('#analyticsSeed').onchange=redraw;redraw();$('#downloadMetrics').onclick=()=>{const protocol=$('#analyticsProtocol').value,items=r.results[protocol].models,rows=[['protocol','method','seed','validation_macro_f1_mean','test_macro_f1_mean','test_macro_f1_std','test_accuracy_mean','false_negatives_mean','false_positive_rate_mean'],...items.map(m=>[protocol,m.method,m.seeds.join('|'),m.validation_macro_f1_mean,m.test.macro_f1.mean,m.test.macro_f1.std,m.test.accuracy.mean,m.test.false_negatives.mean,m.test.false_positive_rate.mean])];downloadText('aesculyn-research-metrics.csv',rows.map(row=>row.map(x=>'"'+String(x).replaceAll('"','""')+'"').join(',')).join('\n'),'text/csv')};redraw()}
function downloadText(name,content,type){const a=document.createElement('a'),u=URL.createObjectURL(new Blob([content],{type}));a.href=u;a.download=name;a.click();URL.revokeObjectURL(u)}

async function settings(){const d=await api('/events');return `<div class="eyebrow">Account & activity</div><h1>Your workspace</h1><p class="sub">Manage your workspace and review recent actions.</p><div class="grid equal"><section class="card"><h2>Workspace details</h2><p class="tiny muted">Signed in as ${esc(user.email)}. No email verification or email password recovery is configured.</p><form class="form" id="workspaceform"><label for="workspaceName">Workspace name</label><input id="workspaceName" name="name" value="${esc(user.workspace)}" maxlength="80" required><button>Save name</button></form></section><section class="card"><h2>Change password</h2><form id="passwordform" class="form"><label for="oldpw">Current password</label><input id="oldpw" name="current_password" type="password" autocomplete="current-password" required><label for="newpw">New password · 12–128 characters</label><input id="newpw" name="new_password" type="password" autocomplete="new-password" minlength="12" maxlength="128" required><button>Change & sign out</button></form></section></div><section class="card"><h2>Recent account activity</h2><div class="table-wrap"><table><thead><tr><th>Action</th><th>Analysis reference</th><th>Time</th></tr></thead><tbody>${d.events.map(e=>`<tr><td>${esc(e.action.replaceAll('_',' '))}</td><td><code>${esc(e.analysis_id||'—')}</code></td><td>${esc(date(e.created))}</td></tr>`).join('')}</tbody></table></div></section>`}
async function detail(id){const d=await api('/analyses/'+id),r=d.analysis;activeId=id;const summary=r.summary;return `<div class="heading"><div><a href="#history" class="tiny">← Analysis history</a><h1>${esc(r.name)}</h1><p class="tiny muted">${esc(date(r.created))} · ${esc(r.model_id)} · ${num(r.rows)} records</p></div>${badge(r)}</div>${summary?`<div class="row toolbar"><a class="button small" href="/api/analyses/${id}/predictions.csv">↓ Predictions CSV</a><a class="button secondary small" href="/api/analyses/${id}/report.json">↓ JSON report</a><a class="button secondary small" href="/api/analyses/${id}/report.html">↓ Printable HTML report</a><button class="danger small" id="delete">Delete analysis</button></div><div class="stats">${stat('Records analyzed',num(r.rows),'Schema validated')}${stat('Predictions to review',num(summary.malicious_predictions),'Non-benign predictions')}${stat('Outside training range',num(summary.out_of_training_range_rows),'At least one feature outside min/max')}${stat('Processing time',summary.inference_ms.toFixed(1)+' ms','Measured batch processing')}</div><div class="grid equal"><section class="card"><h2>Predicted class distribution</h2>${bars(summary.counts)}</section><section class="card"><h2>Input & interpretation checks</h2><p class="tiny">Duplicate feature rows: <b>${summary.validation.duplicate_feature_rows}</b><br>Ignored extra columns: <b>${summary.validation.ignored_columns}</b><br>Missing values: <b>0</b></p><div class="notice">Training range checks are a simple min/max screen, not a drift detector. Softmax scores are uncalibrated. Benign predictions may include false negatives.</div><h3>Input fingerprint</h3><code>${esc(r.input_hash)}</code><p class="tiny muted">${esc(summary.ground_truth)}</p></section></div>${summary.evaluation?`<section class="card" style="margin-bottom:22px"><h2>Evaluation against uploaded labels</h2><div class="metric-pair"><div><b>${pct(summary.evaluation.accuracy)}</b><span>Accuracy</span></div><div><b>${pct(summary.evaluation.macro_f1)}</b><span>Macro-F1 · all 8 classes</span></div><div><b>${summary.evaluation.false_negatives}</b><span>Attack → benign misses</span></div></div><p class="tiny muted">User-supplied labels are not independently verified. Missing classes receive zero in the eight-class macro average. These batch metrics are separate from study test results.</p></section>`:''}<section class="card"><div class="row between"><h2>Record review</h2><label class="tiny">Predicted class <select id="classfilter" style="width:auto"><option value="all">All classes</option>${models[0].classes.map(c=>`<option>${esc(c)}</option>`).join('')}</select></label></div><div id="rows"></div><div class="row between toolbar"><button class="secondary small" id="prev">← Previous</button><span class="tiny muted" id="pageinfo"></span><button class="secondary small" id="next">Next →</button></div><div id="explanation" class="explain-panel" aria-live="polite"></div></section>`:`<section class="card"><h2>${r.status==='failed'?'Analysis needs attention':r.status==='cancelled'?'Analysis cancelled':'Processing your batch'}</h2><div class="progress"><div style="width:${r.progress}%"></div></div><p class="muted">${esc(r.error||(['running','queued'].includes(r.status)?'You can leave this page. Your analysis remains in the background.':r.status))}</p>${['running','queued'].includes(r.status)?'<button class="secondary" id="cancel">Cancel analysis</button>':'<button id="retry">Retry as new analysis</button> <button class="danger" id="delete">Delete analysis</button>'}</section>`}`}
async function rows(){const id=activeId,d=await api(`/analyses/${id}/rows?page=${page}&class=${encodeURIComponent(classFilter)}`);if(activeId!==id)return;$('#rows').innerHTML=`<div class="table-wrap"><table><thead><tr><th>Row (zero-based)</th><th>Prediction</th><th>Review</th><th>Range check</th><th>Supplied label</th><th></th></tr></thead><tbody>${d.rows.map(r=>`<tr><td>${r.row}</td><td>${esc(r.prediction)}</td><td>${r.review?'Review required':'Informational'}</td><td>${r.outside_training_range?'Outside range':'Within range'}</td><td>${esc(r.actual||'Not supplied')}</td><td><button class="secondary small explain" data-row="${r.row}">Explain</button></td></tr>`).join('')}</tbody></table>${d.rows.length?'':'<p class="empty">No records match this class.</p>'}</div>`;$('#pageinfo').textContent=`Page ${page+1} · ${num(d.total)} matching records`;$('#prev').disabled=page===0;$('#next').disabled=(page+1)*20>=d.total;document.querySelectorAll('.explain').forEach(b=>b.onclick=()=>explain(Number(b.dataset.row)))}
async function explain(row){const id=activeId,el=$('#explanation');el.innerHTML='<p class="muted">Calculating local integrated gradients…</p>';try{const d=await api(`/analyses/${id}/explanation?row=${row}`);if(activeId!==id)return;const features=[...d.features].sort((a,b)=>Math.abs(b.contribution)-Math.abs(a.contribution)),max=Math.max(1e-9,...features.map(f=>Math.abs(f.contribution)));el.innerHTML=`<h2>Why this prediction? · Row ${row}</h2><p class="tiny">${esc(d.prediction)} relative to ${esc(d.reference)}. Positive contributions support this margin; negative contributions oppose it.</p>${features.slice(0,12).map(f=>`<div class="bar-row"><span>${esc(f.feature)}</span><div class="track"><div class="fill ${f.contribution<0?'negative':''}" style="width:${Math.abs(f.contribution)/max*100}%"></div></div><b>${f.contribution.toFixed(2)}</b></div>`).join('')}<p class="tiny muted">${esc(d.method)}. Baseline: ${esc(d.baseline)}.<br>Completeness residual: ${d.completeness_residual.toPrecision(4)} · ${d.integration_steps} integration steps · ${d.converged?'within numerical tolerance':'tolerance not reached; interpret cautiously'}.</p><div class="notice">${esc(d.note)}</div><details><summary class="tiny">All input features</summary><div class="features">${d.features.map(f=>`<div><b>${esc(f.feature)}</b>${num(f.value)}</div>`).join('')}</div></details>`}catch(e){el.innerHTML=`<p class="error">${esc(e.message)}</p>`}}
function bind(view){if(view==='new')$('#upload').onsubmit=async e=>{e.preventDefault();const file=$('#file').files[0],b=e.target.querySelector('button');if(!file)return;if(file.size>5000000){$('#uploaderror').innerHTML='<p class="error">Maximum upload size is 5 MB.</p>';return}b.disabled=true;try{const d=await api('/analyses?name='+encodeURIComponent(file.name)+'&model='+encodeURIComponent($('#model').value),{method:'POST',headers:{'Content-Type':'text/csv'},body:file});location.hash='analysis/'+d.analysis.id}catch(err){$('#uploaderror').innerHTML=`<p class="error">${esc(err.message)}</p>`}finally{b.disabled=false}};
if(view==='settings'){ $('#workspaceform').onsubmit=async e=>{e.preventDefault();try{const d=await api('/workspace',{method:'PATCH',body:JSON.stringify(Object.fromEntries(new FormData(e.target)))});user=d.user;toast('Workspace updated.');route()}catch(err){toast(err.message)}};$('#passwordform').onsubmit=async e=>{e.preventDefault();try{await api('/auth/password',{method:'POST',body:JSON.stringify(Object.fromEntries(new FormData(e.target)))});user=null;csrf='';auth();toast('Password changed. Sign in again.')}catch(err){toast(err.message)}}}
if(view==='analysis'){if($('#rows')){page=0;classFilter='all';rows().catch(e=>toast(e.message));$('#classfilter').onchange=()=>{page=0;classFilter=$('#classfilter').value;rows().catch(e=>toast(e.message))};$('#prev').onclick=()=>{page--;rows().catch(e=>toast(e.message))};$('#next').onclick=()=>{page++;rows().catch(e=>toast(e.message))}}if($('#cancel'))$('#cancel').onclick=async()=>{try{await api('/analyses/'+activeId+'/cancel',{method:'POST'});toast('Cancellation requested.');route()}catch(e){toast(e.message)}};if($('#retry'))$('#retry').onclick=async()=>{try{const d=await api('/analyses/'+activeId+'/retry',{method:'POST'});location.hash='analysis/'+d.analysis.id}catch(e){toast(e.message)}};if($('#delete'))$('#delete').onclick=async()=>{if(!confirm('Permanently delete this analysis, its stored features, and results?'))return;try{await api('/analyses/'+activeId,{method:'DELETE',body:JSON.stringify({confirm:activeId})});location.hash='history';toast('Analysis deleted.')}catch(e){toast(e.message)}}}}

async function captures(){const d=await api('/captures');return `<div class="eyebrow">Offline traffic replay</div><h1>Analyze a PCAP</h1><p class="sub">Bounded classic Ethernet / IPv4 / TCP parsing. No packet capture, decryption, or network action.</p><div class="grid"><section class="card"><h2>Upload a capture</h2><form id="pcapform" class="form"><label for="pcap">Classic PCAP · maximum 5 MB / 200,000 packets / 10,000 windows</label><input type="file" id="pcap" accept=".pcap,application/vnd.tcpdump.pcap" required><button>Parse and score rules →</button></form><div class="notice">Supported DICOM ports: TCP 104 and 11112. IPv6, pcapng, fragmented TCP reassembly, encrypted DICOM fields, and PCAP-to-ML inference are unavailable. Pseudonymous source keys stay private to this workspace; raw capture bytes are discarded.</div></section><section class="card"><h2>Saved capture reports</h2>${d.captures.length?`<div class="table-wrap"><table><thead><tr><th>Capture</th><th>Windows</th><th>Rule hits</th><th></th></tr></thead><tbody>${d.captures.map(c=>`<tr><td>${esc(c.name)}</td><td>${num(c.summary.windows)}</td><td>${num(c.summary.incidents)}</td><td><a href="#capture/${c.id}">Review →</a></td></tr>`).join('')}</tbody></table></div>`:'<p class="empty">No PCAPs have been analyzed in this workspace.</p>'}</section></div><section class="card"><h2>Scope and limits</h2><p class="muted">The parser extracts counters and visible preamble / DICOM association indicators for the dry-run rule layer. Its experimental 32-event encoding is recorded for research; the current research MLP was trained on different feature semantics, so this interface does not apply that model to these captures.</p></section>`}
async function captureDetail(id){const d=await api('/captures/'+id),r=d.capture,w=await api('/captures/'+id+'/windows?page=0'),s=r.summary;return `<div class="heading"><div><a href="#captures" class="tiny">← Captures</a><h1>${esc(r.name)}</h1><p class="tiny muted">${date(r.created)} · ${esc(s.mode)}</p></div><a class="button secondary small" href="/api/captures/${id}/report">↓ Capture report</a></div><div class="stats">${stat('Packets inspected',num(s.packets),'No raw packet archive kept')}${stat('TCP port matches',num(s.windows),'Two-second observation windows')}${stat('Windows skipped',num(s.skipped_packets),'Unsupported or nonmatching packets')}${stat('Rule alerts',num(s.incidents),'Dry-run only · none executed')}</div><div class="grid equal"><section class="card"><h2>Rule counts</h2>${Object.keys(s.rules).length?bars(s.rules):'<p>No configured rules fired.</p>'}</section><section class="card"><h2>Risk levels</h2>${bars(Object.fromEntries(Object.entries(s.levels).map(([k,v])=>['Level '+k,v])))}</section></div><section class="card"><h2>First 20 parsed windows</h2><p class="tiny muted">Source addresses are workspace-salted pseudonyms. Window event sequences are experimental and are not used for MLP predictions.</p><div class="table-wrap"><table><thead><tr><th>Timestamp</th><th>Source</th><th>Risk</th><th>Rule indicators</th></tr></thead><tbody>${w.windows.map(x=>`<tr><td>${date(x.timestamp)}</td><td><code>${esc(x.source)}</code></td><td>Level ${x.risk.level} · ${x.risk.action}</td><td>${x.rules.map(h=>esc(h.rule)).join(', ')||'—'}</td></tr>`).join('')}</tbody></table></div>${w.total>20?`<p class="tiny muted">Showing the first 20 of ${num(w.total)} windows. Full report contains all windows.</p>`:''}<div class="notice">${s.limitations.map(esc).join('<br>')}</div><button class="danger small" id="deletecapture" data-id="${id}">Delete private report</button></section>`}
async function incidents(){const params=new URLSearchParams({search:incidentFilter.search||'',status:incidentFilter.status||'all',level:incidentFilter.level||'all',class:incidentFilter.class||'all'});const query=await api('/incidents?'+params);const d=query;return `<div class="eyebrow">Predictions, rule hits and operator review</div><h1>Incident review</h1><p class="sub">Only observed outputs are listed. Proposed actions remain dry-run.</p><div class="stats">${stat('Open incidents',num(d.levels['1']?0:0),'See current filters below')}${stat('Level 1 · watch',num(d.levels['1']||0),'Proposed alert only')}${stat('Level 2 · restrict',num(d.levels['2']||0),'Rate limit proposed; not executed')}${stat('Level 3 · quarantine',num(d.levels['3']||0),'Quarantine proposed; not executed')}</div><section class="card"><form id="incidentfilter" class="row toolbar"><input id="incidentSearch" placeholder="Search class or source hash" style="max-width:240px"><select id="incidentStatus"><option value="all">All review states</option><option value="open">Open</option><option value="acknowledged">Acknowledged</option><option value="resolved">Resolved</option></select><select id="incidentLevel"><option value="all">All levels</option><option value="1">Watch</option><option value="2">Restrict</option><option value="3">Quarantine</option></select><select id="incidentClass"><option value="all">All predicted classes</option>${classes.map(c=>`<option>${esc(c)}</option>`).join('')}</select><button class="small">Filter</button></form><div class="table-wrap"><table><thead><tr><th>Prediction / rule</th><th>Level</th><th>Source</th><th>Analysis</th><th>State</th><th></th></tr></thead><tbody>${query.incidents.map(i=>`<tr><td>${esc(i.prediction)}</td><td>${['','Watch','Restrict','Quarantine'][i.level]}</td><td><code>${esc(i.source)}</code></td><td><a href="#${i.source.startsWith('capture-')?'capture':'analysis'}/${i.source.startsWith('capture-')?i.source.slice(8):i.analysis_id}">${esc(i.source.startsWith('capture-')?i.source.slice(8,16):i.analysis_id.slice(0,8))}</a></td><td>${esc(i.status)}</td><td><a href="#incident/${i.id}">Open →</a></td></tr>`).join('')}</tbody></table>${query.total?'':`<p class="empty">No incidents match. Completed analyses with low risk and no rule hit do not create incidents.</p>`}</div><p class="tiny muted">${num(query.total)} matching incidents · ${query.mode} · no host action has been executed</p></section>`}
async function incidentDetail(id){const {incident:i}=await api('/incidents/'+id),e=i.evidence,r=e.risk;return `<a class="tiny" href="#incidents">← Incident review</a><h1>${esc(i.prediction)} · Level ${i.level}</h1><p class="sub">${date(i.created)} · ${esc(i.source)} · row ${i.row_index}</p><div class="grid"><section class="card"><h2>Evidence summary</h2><p>${esc(e.summary)}</p><div class="metric-pair"><div><b>${(100*r.score).toFixed(1)}%</b><span>Attack score · uncalibrated</span></div><div><b>${['Normal','Watch','Restrict','Quarantine'][i.level]}</b><span>Dry-run level</span></div></div><p class="tiny">Model: ${esc(e.model_id||'Rules only')}<br>Decision: ${esc(r.reason)}<br>Proposed action: ${esc(e.response.proposed_action||r.action)}<br>Executed: <b>No</b></p>${e.rules.length?`<h3>Matching rules</h3>${e.rules.map(h=>`<div class="notice"><b>${esc(h.rule)}</b> · ${esc(h.severity)} · ${esc(h.explanation)}<br>${esc(JSON.stringify(h.evidence))}</div>`).join('')}`:'<p class="muted">No rule was responsible for this model-scored incident.</p>'}</section><section class="card"><h2>Explainability</h2>${e.top_features.length?e.top_features.map(f=>`<div class="bar-row"><span>${esc(f.feature)}</span><div class="track"><div class="fill ${f.contribution<0?'negative':''}" style="width:${Math.min(100,Math.abs(f.contribution)*30)}%"></div></div><b>${f.contribution.toFixed(3)}</b></div>`).join(''):'<p>Rules-only event; displayed evidence identifies the observed trigger.</p>'}<div class="notice">${esc(e.explanation?.method||'Rule evidence is directly measured by the offline parser.')}. Attribution is not causal proof. No source identity is used as a model feature.</div></section></div><section class="card"><h2>Manual review</h2><p>Current state: <b>${esc(i.status)}</b>. This changes the review record only.</p><button id="ack" data-id="${id}" class="secondary">Acknowledge</button> <button id="resolve" data-id="${id}" class="secondary">Resolve</button></section>`}
async function policyPage(){const d=await api('/policy'),p=d.policy,r=d.rules;return `<div class="eyebrow">Offline settings</div><h1>Rules & response thresholds</h1><p class="sub">All response proposals are dry-run. This interface cannot change firewall or container settings.</p><form id="policyform" class="card form"><h2>Risk ladder</h2><div class="grid equal"><div><label for="watch">Watch threshold</label><input type="number" min="0.01" max="0.99" step="0.01" name="watch" id="watch" value="${p.watch}"></div><div><label for="restrict">Restrict threshold</label><input type="number" min="0.02" max="0.99" step="0.01" name="restrict" id="restrict" value="${p.restrict}"></div><div><label for="quarantine">Quarantine threshold</label><input type="number" min="0.03" max="1" step="0.01" name="quarantine" id="quarantine" value="${p.quarantine}"></div><div><label for="release">Release margin</label><input type="number" min="0" max="0.29" step="0.01" name="release_margin" id="release" value="${p.release_margin}"></div><div><label for="cleans">Clean windows to lower a level</label><input type="number" min="1" max="100" name="clean_windows" id="cleans" value="${p.clean_windows}"></div></div><div class="notice">The classifier's softmax outputs are uncalibrated. Thresholds are configurable experiment settings; they do not establish calibrated risk.</div><h2>Observed-field rules</h2>${[['preamble_exec','Executable signature in visible DICOM preamble'],['bad_first_pdu','Invalid first visible DICOM PDU'],['big_pdu_len','Observed PDU length over parser bound'],['unknown_ae','Visible AE title absent from allowlist']].map(([n,l])=>`<label><input type="checkbox" name="rule_${n}" ${r.enabled[n]?'checked':''} style="width:auto;margin-right:8px">${l}</label>`).join('')}<label for="allowedAE">Allowed visible AE titles (one per line, up to 100)</label><textarea id="allowedAE" rows="4" maxlength="1700" style="width:100%;padding:12px;border-radius:9px;border:1px solid #cedde1">${esc(r.allowed_ae.join('\n'))}</textarea><button>Save dry-run policy</button><p id="policymessage" class="tiny muted"></p></form>`}
function bindSafety(view){if(view==='captures')$('#pcapform').onsubmit=async e=>{e.preventDefault();const f=$('#pcap').files[0],b=e.target.querySelector('button');if(f.size>5000000){toast('PCAP exceeds 5 MB.');return}b.disabled=true;try{const d=await api('/captures?name='+encodeURIComponent(f.name),{method:'POST',headers:{'Content-Type':'application/vnd.tcpdump.pcap'},body:f});location.hash='capture/'+d.capture.id}catch(x){toast(x.message)}finally{b.disabled=false}};if(view==='capture'&&$('#deletecapture'))$('#deletecapture').onclick=async()=>{const id=$('#deletecapture').dataset.id;if(!confirm('Delete this capture summary, parsed windows and linked incidents?'))return;try{await api('/captures/'+id,{method:'DELETE',body:JSON.stringify({confirm:id})});location.hash='captures'}catch(e){toast(e.message)}};if(view==='incidents'){$('#incidentSearch').value=incidentFilter.search||'';$('#incidentStatus').value=incidentFilter.status||'all';$('#incidentLevel').value=incidentFilter.level||'all';$('#incidentClass').value=incidentFilter.class||'all';$('#incidentfilter').onsubmit=e=>{e.preventDefault();incidentFilter={search:$('#incidentSearch').value,status:$('#incidentStatus').value,level:$('#incidentLevel').value,class:$('#incidentClass').value};route()}};if(view==='incident'){for(const [id,status] of [['ack','acknowledged'],['resolve','resolved']])$('#'+id).onclick=async()=>{try{await api('/incidents/'+$('#'+id).dataset.id,{method:'PATCH',body:JSON.stringify({status})});toast('Review status saved.');route()}catch(e){toast(e.message)}}}if(view==='policy')$('#policyform').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target),d={mode:'dry-run',policy:{watch:Number(f.get('watch')),restrict:Number(f.get('restrict')),quarantine:Number(f.get('quarantine')),release_margin:Number(f.get('release_margin')),clean_windows:Number(f.get('clean_windows'))},rules:{enabled:{},allowed_ae:$('#allowedAE').value.split('\n').map(x=>x.trim()).filter(Boolean)}};for(const n of ['preamble_exec','bad_first_pdu','big_pdu_len','unknown_ae'])d.rules.enabled[n]=f.has('rule_'+n);try{await api('/policy',{method:'PATCH',body:JSON.stringify(d)});$('#policymessage').textContent='Dry-run policy saved.'}catch(e){$('#policymessage').innerHTML=`<span class="error">${esc(e.message)}</span>`}}}

async function route(){if(!user)return auth();const gen=++generation;clearTimeout(timer);activeId=null;shell();const route=(location.hash.slice(1)||'dashboard').split('/'),view=route[0];try{const [a,m]=await Promise.all([api('/analyses'),api('/models')]);if(gen!==generation)return;analyses=a.analyses;dashboardIncidents=view==='dashboard'?await api('/incidents'):null;models=m.models;defaultModel=m.default;let html;if(view==='new')html=newAnalysis();else if(view==='models')html=registry();else if(view==='evidence')html=await evidence();else if(view==='settings')html=await settings();else if(view==='workbench')html=await workbench();else if(view==='captures')html=await captures();else if(view==='capture')html=await captureDetail(route[1]);else if(view==='incidents')html=await incidents();else if(view==='incident')html=await incidentDetail(route[1]);else if(view==='policy')html=await policyPage();else if(view==='training')html=await trainingJob(route[1]);else if(view==='analysis')html=await detail(route[1]);else if(view==='history')html=`<div class="heading"><div><div class="eyebrow">Saved & traceable</div><h1>Analysis history</h1><p class="sub">Your uploaded batches and their model versions.</p></div><a class="button" href="#new">＋ New analysis</a></div><section class="card">${table(analyses)}</section>`;else html=dashboard();if(gen!==generation)return;$('#content').innerHTML=(m.error?`<p class="error">${esc(m.error)}</p>`:'')+html;bind(view);if(view==='evidence')bindAnalytics(await api('/research'));bindWorkbench(view);bindSafety(view);if(analyses.some(r=>['queued','running'].includes(r.status))&&['dashboard','history','analysis'].includes(view))timer=setTimeout(route,2500)}catch(e){if(gen===generation&&user)$('#content').innerHTML=`<div class="error" role="alert">${esc(e.message)}</div><p><a href="#dashboard">Return to overview</a></p>`}}
window.addEventListener('hashchange',()=>route());(async()=>{try{const d=await api('/session');user=d.user;csrf=d.csrf;await route()}catch{auth()}})();
async function workbench(){const d=await api('/workbench'),a=d.dataset_audit;return `<div class="eyebrow">Code, data & real experiments</div><h1>Local work & training</h1><p class="sub">Inspect the implementation, reproduce training, and follow saved job logs.</p><div class="notice">${esc(d.notice)} New seven-class architecture work is tracked in ARCHITECTURE_AUDIT.md. Training does not block or modify network traffic.</div><div class="stats">${stat('Feature rows',a?num(a.rows):'Unavailable','Authorized local dataset')}${stat('Saved v2 models',d.existing_experiment.report_available?'51':'Unavailable','Existing completed study')}${stat('Aggregation rounds',d.existing_experiment.report_available?'240':'Unavailable','Actual recorded v2 rounds')}${stat('Training access',d.training_enabled?'Enabled':'Read only',d.dataset_available?'Dataset is configured':'Dataset path needs configuration')}</div><div class="grid"><section class="card"><h2>Local source & deliverables</h2><p class="tiny muted">Read the actual files on this server. No arbitrary filesystem paths are accepted.</p><div class="table-wrap"><table><thead><tr><th>File</th><th>Size</th><th></th></tr></thead><tbody>${d.files.map(f=>`<tr><td><code>${esc(f.name)}</code></td><td>${num(f.bytes)} B</td><td><button class="small secondary source-file" data-name="${esc(f.name)}">Open</button></td></tr>`).join('')}</tbody></table></div></section><aside class="stack"><section class="card"><h2>Reproduce the completed v2 study</h2><p class="tiny muted">This runs actual 20-round training across classical models, centralized MLP, local-only MLP, FedAvg and FedProx. It preserves the old eight-class design. Results use a new experiment directory.</p><form id="trainform" class="form"><label for="trainprotocol">Protocol</label><select id="trainprotocol"><option value="unseen_site">A/B training → unseen C</option><option value="temporal_federation">A/B/C → later windows</option></select><label for="trainseed">Seed</label><select id="trainseed"><option>17</option><option>29</option><option>43</option></select><button ${d.training_enabled&&d.dataset_available?'':'disabled'}>Launch actual training</button></form><p class="tiny muted">${d.training_enabled?'Only one training process may run at a time.':'Training is disabled on this server. Use the configured local research server.'}</p></section><section class="card"><h2>Dataset audit</h2>${a?bars(a.class_counts):'<p>Private experiment audit is not installed.</p>'}<p class="tiny muted">One collection run. Predefined site/time/block assignments. Original study tests were previously inspected.</p></section></aside></div><section class="card"><h2>Training jobs</h2><div class="table-wrap"><table><thead><tr><th>Experiment</th><th>Status</th><th>Created</th><th></th></tr></thead><tbody>${d.jobs.map(j=>`<tr><td><code>${j.id.slice(0,12)}</code></td><td>${badge(j)}</td><td>${date(j.created)}</td><td><a href="#training/${j.id}">Open log →</a></td></tr>`).join('')}</tbody></table>${d.jobs.length?'':'<p class="empty">No training jobs launched from this workspace.</p>'}</div></section><section class="card" id="sourcepanel" style="margin-top:22px"><h2>Source viewer</h2><p class="muted">Choose a file above to inspect the local implementation.</p></section>`}
async function trainingJob(id){const d=await api('/workbench/jobs/'+id),j=d.job;return `<div class="eyebrow">Actual backend process</div><h1>Training experiment</h1><p class="tiny muted"><code>${esc(j.id)}</code> · ${date(j.created)}</p><div class="row">${badge(j)} <a class="button secondary small" href="#workbench">← Local work</a>${j.status==='running'?`<button class="danger small" id="canceltrain" data-id="${j.id}">Cancel training</button>`:''}${j.report_available?`<a class="button small" href="/api/workbench/jobs/${j.id}/report">↓ Experiment report</a>`:''}<button class="secondary small" id="refreshtrain">Refresh log</button></div><section class="card" style="margin-top:22px"><h2>Configuration</h2><pre class="source-code">${esc(JSON.stringify(JSON.parse(j.configuration),null,2))}</pre>${j.error?`<p class="error">${esc(j.error)}</p>`:''}<h2>Process output</h2><pre class="source-code">${esc(j.log||'Waiting for the process to produce output…')}</pre></section>`}
function bindWorkbench(view){if(view==='workbench'){document.querySelectorAll('.source-file').forEach(b=>b.onclick=async()=>{try{const d=await api('/workbench/file?name='+encodeURIComponent(b.dataset.name));$('#sourcepanel').innerHTML=`<h2>${esc(d.name)}</h2><pre class="source-code">${esc(d.content)}</pre>`;$('#sourcepanel').scrollIntoView({behavior:'smooth'})}catch(e){toast(e.message)}});$('#trainform').onsubmit=async e=>{e.preventDefault();const b=e.target.querySelector('button');b.disabled=true;try{const d=await api('/workbench/train',{method:'POST',body:JSON.stringify({seed:Number($('#trainseed').value),protocol:$('#trainprotocol').value})});location.hash='training/'+d.job.id}catch(err){toast(err.message)}finally{b.disabled=false}}}if(view==='training'){if($('#canceltrain'))$('#canceltrain').onclick=async()=>{try{await api('/workbench/jobs/'+$('#canceltrain').dataset.id+'/cancel',{method:'POST'});route()}catch(e){toast(e.message)}};$('#refreshtrain').onclick=route}}
